async function strike(env,nick){const now_=Math.floor(Date.now()/1000);const [c,ts]=String(await kv(env,'strk:'+nick)||'0|0').split('|').map(Number);const n=now_-ts<86400?c+1:1;await kv(env,'strk:'+nick,n+'|'+now_);if(n<2)return '⚠️ Сообщение не отправлено: в чате запрещены пошлые предложения. Это предупреждение — в следующий раз чат закроется на сутки.';const u=now_+86400;await kv(env,'mute:'+nick,u);return '🚫 Сообщение не отправлено. '+muteMsg(u)}
