function lifeOf(p){let L;try{L=p.life?JSON.parse(p.life):null}catch(e){}if(!L)L={v:4,n:{food:80,sleep:80,fun:70,soc:60,hyg:80},t:now(),look:{g:'m',sk:'#e0b08a',hc:'#2b1a10',hs:0,sh:'#e8433a',pa:'#2b3a55',ac:''},own:STARTF.map(f=>f[0]),furn:STARTF,wear:['cap'],wall:'#f3e3c8',floor:'#b98a5a',cd:{}};
 for(const k of ['pc','toilet'])if(!L.own.includes(k))L.own.push(k);if(L.v!==4){L.furn=L.own.filter(k=>FPOS[k]).map(k=>[k,...FPOS[k]]);L.v=4}const h=(now()-L.t)/3600;if(h>0){for(const k of NEEDS)L.n[k]=Math.max(0,Math.round((L.n[k]-DECAY[k]*h)*10)/10);L.t=now()}return L}
function mood(L){return Math.round(NEEDS.reduce((a,k)=>a+L.n[k],0)/NEEDS.length)}
function moodK(L){const m=mood(L);return m>=70?1.25:m>=40?1:0.8}
function needUp(p,add){const L=lifeOf(p);for(const k in add)L.n[k]=Math.max(0,Math.min(100,L.n[k]+add[k]));p.life=JSON.stringify(L);return L}
