let LIFECOL=0;async function lifeCol(env){if(LIFECOL===2)return;if(LIFECOL===1){for(let i=0;i<60&&LIFECOL!==2;i++)await new Promise(r=>setTimeout(r,25));return}LIFECOL=1;for(const q of ['ALTER TABLE players ADD COLUMN life TEXT','CREATE TABLE IF NOT EXISTS rel(a TEXT,b TEXT,s INTEGER,ts INTEGER,PRIMARY KEY(a,b))','CREATE TABLE IF NOT EXISTS pos(tg INTEGER PRIMARY KEY,nick TEXT,x REAL,z REAL,r REAL,e TEXT,et INTEGER,ts INTEGER)','ALTER TABLE pos ADD COLUMN lk TEXT','ALTER TABLE pos ADD COLUMN sy TEXT','ALTER TABLE pos ADD COLUMN syt INTEGER','CREATE TABLE IF NOT EXISTS fr(a TEXT,b TEXT,st TEXT,ts INTEGER,PRIMARY KEY(a,b))','CREATE TABLE IF NOT EXISTS rd(a TEXT,b TEXT,ts INTEGER,PRIMARY KEY(a,b))','CREATE TABLE IF NOT EXISTS chat(a TEXT,b TEXT,f TEXT,t TEXT,ts INTEGER)','CREATE INDEX IF NOT EXISTS chat_ab ON chat(a,b,ts)'])try{await env.DB.prepare(q).run()}catch(e){}LIFECOL=2}
