const RANKS=[[0,'Стажёр',1],[150,'Сотрудник',1.2],[500,'Опытный',1.4],[1200,'Старший',1.7],[2500,'Начальник',2]];const rank=x=>{let r=0;for(let i=0;i<RANKS.length;i++)if(x>=RANKS[i][0])r=i;return r};
